const PROJECT_ROOT = path.join(__dirname, '..');
const OUT = path.join(PROJECT_ROOT, 'data', 'misc-jp.js');

const data = {
  v: 1,
  generated: new Date().toISOString(),
  emergency: EMERGENCY_NUMBERS,
  prefPolice: PREF_POLICE,
  volcanoes: ACTIVE_VOLCANOES.map((v) => ({
    n: v.name,
    lat: Math.round(v.lat * PRECISION),
    lng: Math.round(v.lng * PRECISION),
    r: v.region,
  })),
  holidays: HOLIDAYS,
};

const size = writeBundleJs(OUT, 'MISC_JP', data, [
  '// 緊急連絡先 + 都道府県警 + 活火山(主要) + 祝日(2024-2028)',
  '// 出典: 警察庁・消防庁・気象庁活火山一覧・内閣府国民の祝日',
]);

